window.ScripturaLexicons.BDAG_PART_0372 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-01\" data-source=\"BDAG\" data-search=\"ὑπομονή, ῆς, ἡ substantivo feminino paciência; perseverança; expectativa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπομονή, ῆς, ἡ</td><td>substantivo feminino</td><td>paciência; perseverança; expectativa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-02\" data-source=\"BDAG\" data-search=\"ὑπομονητικός, ή, όν adjetivo paciente; perseverante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπομονητικός, ή, όν</td><td>adjetivo</td><td>paciente; perseverante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-03\" data-source=\"BDAG\" data-search=\"ὑπονοέω verbo suspeitar; supor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπονοέω</td><td>verbo</td><td>suspeitar; supor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-04\" data-source=\"BDAG\" data-search=\"ὑπόνοια, ας, ἡ substantivo feminino suspeita; conjectura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπόνοια, ας, ἡ</td><td>substantivo feminino</td><td>suspeita; conjectura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-05\" data-source=\"BDAG\" data-search=\"ὑποπιάζω remissão v. ὑπωπιάζω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποπιάζω</td><td>remissão</td><td>v. ὑπωπιάζω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-06\" data-source=\"BDAG\" data-search=\"ὑποπίπτω verbo prostrar-se; enquadrar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποπίπτω</td><td>verbo</td><td>prostrar-se; enquadrar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-07\" data-source=\"BDAG\" data-search=\"ὑποπλέω verbo navegar a sotavento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποπλέω</td><td>verbo</td><td>navegar a sotavento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-08\" data-source=\"BDAG\" data-search=\"ὑποπνέω verbo soprar suavemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποπνέω</td><td>verbo</td><td>soprar suavemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-09\" data-source=\"BDAG\" data-search=\"ὑποπόδιον, ου, τό substantivo neutro escabelo; apoio para os pés BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποπόδιον, ου, τό</td><td>substantivo neutro</td><td>escabelo; apoio para os pés</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-10\" data-source=\"BDAG\" data-search=\"ὑποπτεύω verbo suspeitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποπτεύω</td><td>verbo</td><td>suspeitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-11\" data-source=\"BDAG\" data-search=\"ὑπορθόω verbo sustentar; ajudar a ficar ereto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπορθόω</td><td>verbo</td><td>sustentar; ajudar a ficar ereto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-12\" data-source=\"BDAG\" data-search=\"ὑπόστασις, εως, ἡ substantivo feminino essência; realidade; empreendimento; condição; título de propriedade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπόστασις, εως, ἡ</td><td>substantivo feminino</td><td>essência; realidade; empreendimento; condição; título de propriedade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-13\" data-source=\"BDAG\" data-search=\"ὑποστέλλω verbo recuar; retirar-se; esquivar-se; calar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποστέλλω</td><td>verbo</td><td>recuar; retirar-se; esquivar-se; calar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-14\" data-source=\"BDAG\" data-search=\"ὑποστολή, ῆς, ἡ substantivo feminino hesitação; timidez BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποστολή, ῆς, ἡ</td><td>substantivo feminino</td><td>hesitação; timidez</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-15\" data-source=\"BDAG\" data-search=\"ὑποστρέφω verbo voltar; retornar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποστρέφω</td><td>verbo</td><td>voltar; retornar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-16\" data-source=\"BDAG\" data-search=\"ὑποστρωννύω/ὑποστρώννυμι verbo estender por baixo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποστρωννύω/ὑποστρώννυμι</td><td>verbo</td><td>estender por baixo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-17\" data-source=\"BDAG\" data-search=\"ὑποταγή, ῆς, ἡ substantivo feminino submissão; sujeição; subordinação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποταγή, ῆς, ἡ</td><td>substantivo feminino</td><td>submissão; sujeição; subordinação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-18\" data-source=\"BDAG\" data-search=\"ὑποτάσσω verbo sujeitar; subordinar; obedecer; anexar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποτάσσω</td><td>verbo</td><td>sujeitar; subordinar; obedecer; anexar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-19\" data-source=\"BDAG\" data-search=\"ὑποτεταγμένως advérbio submissamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποτεταγμένως</td><td>advérbio</td><td>submissamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0372-20\" data-source=\"BDAG\" data-search=\"ὑποτίθημι verbo depor; arriscar; instruir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποτίθημι</td><td>verbo</td><td>depor; arriscar; instruir</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0372-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπομονή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπομονή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὑπομένω</span>)</p><p class=\"entry-text\">① Capacidade de resistir ou suportar diante da dificuldade, paciência, resistência, fortaleza, firmeza, perseverança (Ps.-Pla., Def. 412c; Aristot., estoicos [Stoic. IV 150 índice; Musonius; Epict.—PBarth, D. Stoa4 1922, 119ff]; Polyb., Plut., LXX; PsSol 2:36; TestJob 1:5; TestJos; Philo; Jos., Ant. 3, 16 al.; Just.; ao lado de <span class=\"greek\">καρτερία</span> Orig., C. Cels. 7, 55, 6; <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὑπομονὴν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">ἀγαθῶν</span> Theoph. Ant. 1, 14 [p. 90, 17]), esp. conforme se manifestam ao suportar fadigas e sofrimentos Lk 21:19; Rom 5:3f (sobre a forma de ‘clímax’ do dito cf. Maximus Tyr. 16, 3b <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρετὴν</span> <span class=\"greek\">διδόασιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span>, <span class=\"greek\">τοὺς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἄσκησις</span>, <span class=\"greek\">τὴν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἄσκησιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀλήθεια</span>, <span class=\"greek\">τὴν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἀλήθειαν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σχολή</span>); 15:4f; 2 Cor 6:4; 1 Th 1:3; 2 Th 1:4; 1 Ti 6:11; 2 Ti 3:10; Tit 2:2; Hb 10:36; Js 1:3f; 2 Pt 1:6ab; Rv 2:2f, 19; 1 Cl 5:5, 7; B 2:2; IEph 3:1; Hm 8:9; D 5:2. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ὑπ</span>. toda espécie de paciência 2 Cor 12:12; Col 1:11. Com gen. subjetivo <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπ</span>. <span class=\"greek\">Ἰώβ</span> Js 5:11 (ACarr, The Patience of Job [Js 5:11]: Exp. 8th ser., 6, 1913, 511–17); <span class=\"greek\">αὐτοῦ</span> (i.e., <span class=\"greek\">Χριστοῦ</span>) a perseverança que Cristo demonstrou Pol 8:2. Diferentemente <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> uma fortaleza semelhante à de Cristo, i.e., uma fortaleza proveniente da associação com Cristo 2 Th 3:5 (OSchmitz, D. Christusgemeinschaft des Pls im Lichte seines Genetivbrauchs 1924, 139f); cf. IRo 10:3 (v. também 2 abaixo). Com gen. objetivo <span class=\"greek\">ὑπ</span>. <span class=\"greek\">ἔργου</span> <span class=\"greek\">ἀγαθοῦ</span> perseverança em fazer o que é reto Ro 2:7 (Polyb. 4, 51, 1 <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πολέμου</span>). <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">παθημάτων</span> firme perseverança nos sofrimentos 2 Cor 1:6 (Ps.-Pla., Def. 412c <span class=\"greek\">ὑπ</span>. <span class=\"greek\">λύπης</span>; Plut., Pelop. 278 [1, 8] <span class=\"greek\">ὑπ</span>. <span class=\"greek\">θανάτου</span>; Jos., Ant. 2, 7 <span class=\"greek\">πόνων</span> <span class=\"greek\">ὑπ</span>.). <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑπομονῆς</span> <span class=\"greek\">μου</span> (<span class=\"greek\">λόγος</span> 1a<span class=\"greek\">β</span>) Rv 3:10 (v. também 2 abaixo). <span class=\"greek\">δι</span>’ <span class=\"greek\">ὑπομονῆς</span> com paciência ou fortaleza Ro 8:25; Hb 12:1. <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑπομονῆς</span> por meio de sua paciente perseverança MPol 19:2 (Just., A I, 16, 3). <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑπομονῇ</span> (PsSol 2:36; TestJos 10:2) Lk 8:15 (LCerfaux, RB 64, ’57, 481–91). <span class=\"greek\">ὑπομένειν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ὑπομονήν</span> exercer a perseverança até o limite Pol 9:1. <span class=\"greek\">ὧδέ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> aqui está (uma oportunidade para) a perseverança da parte dos santos (Weymouth) Rv 13:10 (v. JSchmid, ZNW 43, ’50/51, 112–28); cf. 14:12. Texto incerto <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τ̣ῶ̣ν̣</span> <span class=\"greek\">ὑ</span>[<span class=\"greek\">πο</span>]<span class=\"greek\">μ̣ονῶν</span> AcPl Ha 6, 11f.—WMeikle, The Vocabulary of ‘Patience’ in the OT: Exp. 8th ser., 19, 1920, 219–25, The Voc. etc. in the NT: ibid. 304–13; CSpicq, Patientia: RSPT 19, 1930, 95–106; AFestugière, RSR 21, ’31, 477–86; LMarshall, Challenge of NT Ethics ’47, 91f.</p><p class=\"entry-text\">② Ato ou estado de esperar pacientemente por alguém ou algo, expectativa (Ps 9:19; 61:6; 2 Esdr 10:2) Rv 1:9 (sobre <span class=\"greek\">ὑπ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἰησοῦ</span> v. IHeikel, StKr 106, ’35, 317). Talvez (v. 1 acima) 3:10 e 2 Th 3:5; IRo 10:3 também possam ser classificados aqui (assim Lightf.).—RAC IX 658–65. DDenton observa estreita relação com <span class=\"greek\">ἐλπίς</span>: SJT 34, ’81, 313–20. V. <span class=\"greek\">ὑπομένω</span>, final.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπομονητικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπομονητικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">ὑπομονή</span>; Hippocr.+; Philo, Leg. All. 3, 88) relativo a ser capaz de resistir diante da dificuldade, paciente, que demonstra perseverança; subst. neutro <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπομονητικόν</span> fortaleza MPol 2:2.—DELG s.v. <span class=\"greek\">μένω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπονοέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπονοέω</span> imperf. <span class=\"greek\">ὑπενόουν</span>; fut. 3 sg. <span class=\"greek\">ὑπονοήσει</span> Da 7:25 Theod.; 1 aor. <span class=\"greek\">ὑπενόησα</span> (v. verbete seguinte; Eur., Hdt. et al.; papiros, LXX; TestBenj 9:1; Philo, Joseph.; Just., D. 103, 3; 125, 1) formar uma opinião ou conjectura com base em indícios escassos, suspeitar, supor (Hdt. et al.; papiros; Sir 23:21) com acus. de algo (Hdt., Aristoph. et al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:18</a> (com atração do relativo; cf. PLond 1912, 97f <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">μείζονας</span> <span class=\"greek\">ὑπονοίας</span> <span class=\"greek\">ἀναγκασθήσομαι</span> <span class=\"greek\">λαβεῖν</span>). Seguido de acus. e inf. (B-D-F §397, 2; Rob. 1036.—Hdt. 9, 99 al.; Jos., Ant. 13, 315; Just.; PRyl 139, 14 [34 d.C.]) 13:25; 27:27; cf. Hv 4, 1, 6.—DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπόνοια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπόνοια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὑπονοέω</span>; Thu. et al.; papiros, LXX; EpArist 316; Philo; Jos., Bell. 1, 227; 631; Ath. 1, 4) opinião ou conjectura baseada em indícios escassos, suspeita, conjectura <span class=\"greek\">ὑπόνοιαι</span> <span class=\"greek\">πονηραί</span> conjecturas malignas, falsas suspeitas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:4</a> (Sir 3:24 <span class=\"greek\">ὑπόνοια</span> <span class=\"greek\">πονηρά</span>).—B. 1244. DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποπιάζω</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποπιάζω</span> v. <span class=\"greek\">ὑπωπιάζω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποπίπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποπίπτω</span> 2 aor. <span class=\"greek\">ὑπέπεσον</span> (Thu., Aristoph.+; inscr., papiros, LXX; TestJos 7:8; EpArist 214; Philo; Jos., Bell. 5, 382, Vi. 381; Just.)</p><p class=\"entry-text\">① De pessoas, fazer o gesto de um suplicante, ajoelhando-se ou prostrando-se, prostrar-se diante de <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ὑποπέσῃς</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δεηθῇς</span> <span class=\"greek\">αὐτοῦ</span> se te prostrares diante de (Deus) e suplicares a (Deus) AcPl Ha 9, 12.</p><p class=\"entry-text\">② De coisas, estar incluído em alguma classificação, enquadrar-se em algo <span class=\"greek\">ὑπό</span> <span class=\"greek\">τι</span> (Aristot.; Iambl., Vi. Pythag. 34 §241 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">προειρημένην</span> <span class=\"greek\">τάξιν</span>) <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιάν</span> <span class=\"greek\">τινος</span> estar ao alcance da compreensão de alguém (<span class=\"greek\">διάνοια</span> 1) 1 Cl 35:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποπλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποπλέω</span> 1 aor. <span class=\"greek\">ὑπέπλευσα</span> (Dio Chrys., Cass. Dio et al.) navegar a sotavento de uma ilha, i.e., de tal maneira que a ilha proteja o navio do vento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:4</a>, 7.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποπνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποπνέω</span> 1 aor. <span class=\"greek\">ὑπέπνευσα</span> (Aristot., Probl. 8, 6=soprar por baixo) soprar suavemente <span class=\"greek\">ὑποπνεύσαντος</span> <span class=\"greek\">νότου</span> quando começou a soprar um vento moderado do sul (sudoeste) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:13</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποπόδιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποπόδιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πούς</span>; Chares [depois de 323 a.C.]: 125 Fgm. 2 p. 658, 22 Jac. [em Athen. 12 p. 514f]; Lucian, Hist. Conscrib. 27; Athen. 5, 192e; inscr.; PTebt 45, 38 [113 a.C.]; CPR 22, 8; 27, 11 [ambos II d.C.]; LXX; empréstimo na literatura rabínica) escabelo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:3</a>. Da terra como escabelo de Deus (segundo Is 66:1; cf. Philo, Conf. Lingu. 98) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:49</a>; B 16:2. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ὑποπόδιον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">τινος</span> fazer de alguém escabelo para alguém, i.e., sujeitar uma pessoa a outra, de modo que esta possa pôr um pé sobre o pescoço da pessoa sujeita (Ps 109:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:44</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:36</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:13</a>; 10:13; 1 Cl 36:5; B 12:10.—DELG s.v. <span class=\"greek\">πούς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποπτεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποπτεύω</span> (cf. <span class=\"greek\">ὑφοράω</span>: fut. <span class=\"greek\">ὑπόψομαι</span>, ‘olhar de baixo, olhar furtivamente’; v. <span class=\"greek\">ὑποψία</span>) 1 aor. <span class=\"greek\">ὑπώπτευσα</span>, inf. pass. <span class=\"greek\">ὑποπτευθῆναι</span> (Ath.) (Trag., Thu. et al.; papiros, LXX; En 101:5; Jos., Bell. 2, 617; 3, 367; Just., A II, 3, 3; Ath. 31, 2) suspeitar de <span class=\"greek\">τινά</span> alguém (Soph., Hdt., Thu. et al.) seguido de acus. e inf. IPhld 7:2.—DELG s.v. <span class=\"greek\">ὄπωπα</span> B 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπορθόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπορθόω</span> (Sym.; Dositheus, Ars Gramm. 76, 1 p. 102) ajudar a manter-se ereto, sustentar <span class=\"greek\">τινά</span> alguém GPt 10:39.—DELG s.v. <span class=\"greek\">ὀρθός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπόστασις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπόστασις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὑφίστημι</span>; Hippocr.+; Polyb. 4, 50, 10; 6, 55, 2; Diod S 16, 32, 3; 16, 33, 1; M. Ant. 10, 5; inscr., papiros, LXX; PsSol 15:5; 17:24; TestReub 2:7; TestZeb 2:4; Tat.; Ath. 21, 3; Iren. 5, 36, 1 [Harv. II 426, 1]; Hippol., Ref. 10, 17, 2; Did., Gen. 128, 11 em sentidos amplamente diferentes. V. Dörrie 4 abaixo.)</p><p class=\"entry-text\">① Estrutura/natureza essencial ou básica de uma entidade, natureza substancial, essência, ser efetivo, realidade (estrutura subjacente, freq. em contraste com o que meramente parece ser: Ps.-Aristot., De Mundo 4 p. 395a, 29f; Plut., Mor. 894b; Diog. L., Pyrrh. 9, 91; Artem. 3, 14; Ps 38:6; Wsd 16:21; TestReub 2:7; SJCh 78, 30; Philo, Aet. M. 88; 92; Jos., C. Ap. 1, 1; Tat. 6, 2; Ath. 21, 3; cf. a resposta de certo Secundo, que, quando lhe perguntaram ‘Quid fides?’, respondeu: ‘ignotae rei mira certitudo’=uma certeza admirável acerca de algo de outro modo desconhecido [FPhGr I 516]; v. também Lexicon Sabbaiticum: Lexica Graeca Minora ’65, 53)</p><p class=\"entry-text\">ⓐ Do Filho de Deus como <span class=\"greek\">χαρακτὴρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑποστάσεως</span> <span class=\"greek\">αὐτοῦ</span> uma representação exata do ser real (de Deus) (i.e., como aquele que está encarregado do universo) Hb 1:3. Semelhantemente, das divindades dos politeístas, cuja realidade fundamental é algo material, como pedra, metal etc. Dg 2:1.</p><p class=\"entry-text\">ⓑ De coisas: entre os sentidos que podem ser autenticados para Hb 11:1, pode-se defender com fortes argumentos a realização (Diod S 1, 3, 2 da realização de um plano; Cornutus 9 p. 9, 3 da realização da humanidade; Jos., C. Ap. 1, 1 a do povo judeu, ambas por um ato divino; Tat. 5, 1 de Deus <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπόστασις</span>): <span class=\"greek\">ἔστιν</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">ἐλπιζομένων</span> <span class=\"greek\">ὑπ</span>.=na fé, as coisas esperadas se realizam, ou as coisas esperadas adquirem (mas v. 3 e 4 abaixo) realidade. Inversamente, ‘sem fé as coisas esperadas não teriam realidade’. HKöster (v. bibliog. 4 abaixo) argumenta em favor deste sentido também em 3:14, mas v. 2. Cf. a tradução ‘substância’ (p. ex., KJV, REB).</p><p class=\"entry-text\">② Plano que alguém elabora para agir, plano, projeto, empreendimento, esforço (Diod. Sic 15, 70, 2; 16, 32, 3; 16, 82, 6; 17, 69, 7; Ezk 19:5) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὑποστάσει</span> <span class=\"greek\">ταύτῃ</span> em relação com este empreendimento, i.e., a coleta para Jerusalém 2 Cor 9:4. O fato de que o cumprimento de uma obrigação financeira é o tema principal (vv. 1–2) bem poderia sugerir a associação de <span class=\"greek\">ὑπ</span>. com seu emprego, p. ex., como termo técnico da expectativa de aluguel devido PTebt 61b, 194. Para enfatizar a importância do compromisso firme com a obrigação professada (em oposição a <span class=\"greek\">καρδία</span> <span class=\"greek\">πονηρὰ</span> <span class=\"greek\">ἀπιστίας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀποστῆναι</span>), o autor de Hb 3:14 emprega <span class=\"greek\">ὑπ</span>. de modo que convida o destinatário a recorrer ao componente semântico de obrigação, familiar no uso comercial do termo (v. PTebt acima), associação sugerida pelo emprego de <span class=\"greek\">μέτοχος</span>, termo habitual para um sócio comercial (PHib 109, 3; PCairZen 176, 102 [ambos III a.C.]), <span class=\"greek\">μέχρι</span> <span class=\"greek\">τέλους</span> (s.v. <span class=\"greek\">τέλος</span> 2b<span class=\"greek\">β</span>) e <span class=\"greek\">βέβαιος</span> (v. M-M s.v.). V. Köster 1b acima quanto à ênfase de <span class=\"greek\">ὑπ</span>. na ‘realidade’.—Satiricamente, <span class=\"greek\">ἐν</span> <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὑποστάσει</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καυχήσεως</span> neste meu empreendimento de jactância 2 Cor 11:17.</p><p class=\"entry-text\">③ A interpretação situação, condição (Cicero, Ad Attic. 2, 3, 3 <span class=\"greek\">ὑπόστασιν</span> nostram=nossa situação), também especificamente disposição de espírito (Dio Cass. 49, 9; Themist., Or. 13 p. 178b; Jos., Ant. 18, 24 de determinação em circunstâncias desesperadoras; semelhantemente Polyb. 6, 55, 2) tem sido sugerida para algumas das passagens citadas em 1 e 2 acima: 2 Cor 9:4 (explicada numa v.l. pelo gen. epexegético <span class=\"greek\">καυχήσεως</span>); 11:17; Hb 3:14 (v. Dörrie [bibliog. 4 abaixo], p. 39: a disposição de espírito descrita em Hb 3:6). O sentido ‘confiança’, ‘segurança’ (baseado na LXX [Ruth 1:12; Ps 38:8; Ezk 19:5], onde traduz <span class=\"hebrew\" dir=\"rtl\">תִּקְוָה</span> etc.) favorecido por Melanchthon e Lutero (também Tyndale, NRSV, mas não KJV) para Hb 11:1 tem gozado de grande aceitação, mas deve ser eliminado, visto que não se encontram exemplos dele (v. Dörrie e Köster [4 abaixo]). Mais provável para Hb 4:11 é</p><p class=\"entry-text\">④ Garantia de propriedade/direito, título de propriedade (Sb 9086 III, 1–11 [104 d.C.]; Spicq III 423 n. 14; cf. M-M s.v.) Hb 11:1 (cf. 2 acima quanto ao uso comercial de <span class=\"greek\">ὕπ</span>.).—ASchlatter, Der Glaube im NT4 1927, 614ff; MMathis, The Pauline <span class=\"greek\">πίστισ</span>-<span class=\"greek\">ὑπόστασις</span> acc. to Hb 11:1, diss. Cath. Univ. of Amer., Washington, D.C. 1920, também Biblica 3, 1922, 79–87; RWitt, Hypostasis: ‘Amicitiae Corolla’ (RHarris Festschr.) ’33, 319–43; MSchumpp, D. Glaubensbegriff des Hb: Divus Thomas 11, ’34, 397–410; FErdin, D. Wort Hypostasis, diss. Freiburg ’39; CArpe, Philologus 94, ’41, 65–78; HDörrie, <span class=\"greek\">Ὑπόστασις</span>, Wort-u. Bedeutungsgeschichte: NAWG 1955, n.º 3, ZNW 46, ’55, 196–202; HKöster, TW VIII 571–88 (Köster prefere plano, projeto [Vorhaben] para as passagens em 2 Cor, e realidade [Wirklichkeit] para todas as 3 ocorrências em Hb, contrapondo a realidade de Deus ao caráter transitório do mundo visível). V. também a bibliografia s.v. <span class=\"greek\">πίστις</span> 2a.—DELG s.v. <span class=\"greek\">ἵστημι</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποστέλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποστέλλω</span> imperf. <span class=\"greek\">ὑπέστελλον</span>; 1 aor. méd. <span class=\"greek\">ὑπεστειλάμην</span> (v. <span class=\"greek\">ὑποστολή</span>; Pind. et al.; inscr., papiros, LXX, Philo, Joseph.)</p><p class=\"entry-text\">① Recuar ou desaparecer de uma posição</p><p class=\"entry-text\">ⓐ At. (Pind. et al.; Philo, Leg. ad Gai. 71) recuar, retirar (Polyb. 1, 21, 2 al.; Plut.) <span class=\"greek\">ἑαυτόν</span> retirar(-se) (Polyb. 1, 16, 10; 7, 17, 1 al.) <span class=\"greek\">ὑπέστελλεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀφώριζεν</span> <span class=\"greek\">ἑαυτόν</span> Gal 2:12; se <span class=\"greek\">ἑαυτόν</span> não se constrói com <span class=\"greek\">ὑπέστ</span>., <span class=\"greek\">ὑποστέλλω</span> é aqui intr., recuar (Polyb. 6, 40, 14; 10, 32, 3; Plut., Demetr. 912 [47, 6]; Philo, Spec. Leg. 1, 5).</p><p class=\"entry-text\">ⓑ Méd. recuar <span class=\"greek\">ἡ</span> <span class=\"greek\">νεφέλη</span> <span class=\"greek\">ὑπεστέλλετο</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σπηλαίου</span> a nuvem se dissipou, afastando-se da caverna GJs 19:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐκεῖνο</span> <span class=\"greek\">ὑπεστέλλετο</span> aquela luz se dissipou ibid.</p><p class=\"entry-text\">② Hesitar em relação a algo, méd.</p><p class=\"entry-text\">ⓐ Recuar (Aelian, NA 7, 19; Philo, Mos. 1, 83; Jos., Vi. 215) Hb 10:38 (Hab 2:4).</p><p class=\"entry-text\">ⓑ Esquivar-se de, evitar, com implicação de medo (Demosth. et al.; Jos., Ant. 6, 86 <span class=\"greek\">ὑπ</span>. <span class=\"greek\">φόβῳ</span> <span class=\"greek\">εἰπείν</span>) <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὑπεστειλάμην</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀναγγεῖλαι</span> não me esquivei de proclamar Ac 20:27.</p><p class=\"entry-text\">ⓒ Ter receio de, calar a respeito de, méd. <span class=\"greek\">τὶ</span> algo por medo (Demosth. 4, 51; Isocr. 8, 41; Diod S 13, 70, 3 Ciro exorta Lisandro a não ter receio de pedir dinheiro; Dio Chrys. 10 [11], 27 <span class=\"greek\">οὐδέν</span>; Lucian, Deor. Conc. 2 <span class=\"greek\">οὐδέν</span>; PCairZen 412, 24 [III a.C.]; BGU 1303, 10; Philo, Sacr. Abel. 35; Jos., Bell. 1, 387, Vi. 278 <span class=\"greek\">οὐδέν</span> al.) <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὑπεστειλάμην</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">συμφερόντων</span> nada calei do que é proveitoso Ac 20:20.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποστολή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποστολή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὑποστέλλω</span>) estado de ser tímido, hesitação, timidez (Asclepiodot. Tact. [I a.C.] 10, 21 de manter um corpo de tropas em posição de reserva.—Jos., Bell. 2, 277, Ant. 16, 112 de pessoas que não têm escrúpulos em entregar-se à vileza) <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐσμὲν</span> <span class=\"greek\">ὑποστολῆς</span> não pertencemos aos que são tímidos, em contraste com aqueles que estão sinceramente empenhados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:39</a>.—DELG s.v. <span class=\"greek\">στέλλω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποστρέφω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποστρέφω</span> imperf. <span class=\"greek\">ὑπέστρεφον</span>; fut. <span class=\"greek\">ὑποστρέψω</span>; 1 aor. <span class=\"greek\">ὑπέστρεψα</span>; em nossa literatura somente intr. (Hom.+; Thu.; papiros, LXX; Test-Abr B 12 p. 117, 2 e 5 [Stone p. 82] trans.; TestJob 7:9; TestZeb 4:6 v.l.; TestGad 1:5; ParJer, Philo, Joseph.; Just., D. 56, 22) voltar, retornar com <span class=\"greek\">εἰς</span> e acus. de lugar (PGiss 40 II, 8; Gen 8:9; ParJer 5:12; 8:8; Jos. Bell. 1, 229 <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἱερος</span>.; Just., D. 56, 22 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">αὐτοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:56</a>; 2:45; 4:14 (cf. Jos., Bell. 1, 445); 8:39 (cf. Jos., Vi. 144 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:25</a>; 13:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:17</a>; GPt 14:58. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:6</a> (<span class=\"greek\">ἴδιος</span> 4b). <span class=\"greek\">εἰς</span> <span class=\"greek\">διαφθοράν</span> para a corrupção, i.e., o sepulcro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:34</a>. <span class=\"greek\">διά</span> com gen. de lugar 20:3. <span class=\"greek\">ἀπό</span> com gen. de lugar (Jos., Vi. 139) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:1</a>; 24:9 ou uma expressão correspondente (Jos., Vi. 329 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πολιορκίας</span> <span class=\"greek\">ὑπ</span>.) <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κοπῆς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βασιλέων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:1</a> (Gen 14:17). <span class=\"greek\">εἰς</span> e <span class=\"greek\">ἀπό</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:12</a>. <span class=\"greek\">ἐκ</span> com gen. de lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:25</a> v.l. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁγίας</span> <span class=\"greek\">ἐντολῆς</span> afastar-se e retornar ao antigo padrão de crença (v. <span class=\"greek\">ἐντολή</span> 2b<span class=\"greek\">ζ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:21</a> (cf. <span class=\"greek\">ἀνακάμπτω</span> e <span class=\"greek\">ἐπιστρέφω</span>). <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> a alguém Hm 4, 1, 7. Seguido de inf. final <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:18</a>. Abs. retornar (Polyaenus 4, 2, 14; Lucian Bis Acc. 17; Josh 2:23; Jos., Ant. 11, 30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:40</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:20</a>, 43; 8:37, 40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:28</a> al.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποστρωννύω/ὑποστρώννυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποστρωννύω</span>/<span class=\"greek\">ὑποστρώννυμι</span> (cf. <span class=\"greek\">στρωννύω</span>, início.—A palavra ocorre em Hom. et al. [<span class=\"greek\">ὑποστορέννυμι</span>, <span class=\"greek\">ὑποστόρνυμι</span>]; LXX; JosAs 10:16 cod. A [p. 52, 20 Bat.]. Na forma <span class=\"greek\">ὑποστρωννύω</span> em Athen. 2, 48d; na forma <span class=\"greek\">ὑποστρώννυμι</span> em Plut., Artox. 1022 [22, 10]) imperf. <span class=\"greek\">ὑπεστρώννυον</span>; 1 aor. <span class=\"greek\">ὑπέστρωσα</span>; estender por baixo, <span class=\"greek\">τὶ</span> algo (PGM 5, 217 <span class=\"greek\">σινδόνα</span>; 36, 151) <span class=\"greek\">ὑπεστρώννυον</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span> estendiam seus mantos sob ele no caminho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:36</a> (Jos., Ant. 9, 111 <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">ὑπεστρώννυεν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱμάτιον</span>; 18, 204; Chariton 3, 2, 17; Aesop, Fab. 208 P.=378 H. <span class=\"greek\">ὑποστρώσας</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱμάτιον</span>). <span class=\"greek\">σποδόν</span> estender cinzas debaixo de si = fazer seu leito em cinzas como sinal de arrependimento B 3:2 (Is 58:5; cf. JosAs 10:16 cod. A). Pass. <span class=\"greek\">κήρυκας</span> <span class=\"greek\">ὑποστρωννύμενοι</span> aqueles que têm conchas de trombeta (<span class=\"greek\">κῆρυξ</span> 3) debaixo de si=aqueles que foram deitados sobre conchas de trombeta MPol 2:4. —DELG e Frisk s.v. <span class=\"greek\">στόρνυμι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποταγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποταγή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (v. <span class=\"greek\">ταγή</span>, e cf. 2 aor. de <span class=\"greek\">ὑποτάσσω</span>; Dionys. Hal. 3, 66, 3 at. ‘sujeitar’) em nossa literatura somente pass., estado de submissão, sujeição, subordinação, em oposição a colocar-se como controlador (Plut., Mor. 142e) (Wsd 18:15 A; TestSol; ApcMos 10; Artem. 1, 73 p. 66, 14; Paradoxogr. p. 218, 7 Westermann <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑποταγῇ</span>; Vett. Val. 106, 8; 11; 17; 24; 198, 28; BGU 96, 7 [III a.C.] <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑποταγῇ</span> <span class=\"greek\">τυγχάνοντα</span>. Cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑπ</span>. <span class=\"greek\">μένειν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Iren. 4, 38, 3 [Harv. II 196, 3]; Theoph. Ant 1, 6 [p. 70, 11]). <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑποταγὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁμολογίας</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:13</a> (<span class=\"greek\">ὁμολογία</span> 1). <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">ὑποταγῇ</span> subordinando-se em todos os aspectos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:11</a> (cf. cum omni subiectione Papias [1:3]); <span class=\"greek\">τέκνα</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑποταγῇ</span> manter os filhos sob controle 3:4. <span class=\"greek\">ἐν</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">ὑποταγῇ</span> <span class=\"greek\">κατηρτισμένοι</span> aperfeiçoados em submissão unânime IEph 2:2. <span class=\"greek\">εἴξαμεν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὑποταγῇ</span> (dat. de modo) cedemos em submissão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:5</a>. O sistema de relações ordenadas requer o reconhecimento do lugar próprio de cada um na estrutura. Visto que Paulo está subordinado à ‘verdade do evangelho’, não pode acatar certas exigências impostas por dirigentes em Jerusalém, que têm a obrigação de reconhecer seu lugar na ordem das coisas.—Dos membros do corpo <span class=\"greek\">ὑποταγῇ</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">χρῆται</span> experimentam uma sujeição mútua 1 Cl 37:5. <span class=\"greek\">ὁ</span> <span class=\"greek\">κανὼν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑποταγῆς</span> a norma estabelecida de obediência (Kleist) 1:3.—DELG s.v. <span class=\"greek\">τάσσω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποτάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποτάσσω</span> 1 aor. <span class=\"greek\">ὑπέταξα</span>. Pass.: 2 fut. <span class=\"greek\">ὑποταγήσομαι</span>; 2 aor. <span class=\"greek\">ὑπετάγην</span>; perf. <span class=\"greek\">ὑποτέταγμαι</span> (Aristot., Polyb.+)</p><p class=\"entry-text\">① Fazer estar numa relação de submissão, sujeitar, subordinar</p><p class=\"entry-text\">ⓐ At., abs. Ro 8:20b; 1 Cl 2:1b. <span class=\"greek\">τινά</span> levar alguém à sujeição (Herodian 7, 2, 9) IPol 2:1. <span class=\"greek\">τινί</span> <span class=\"greek\">τινα</span> ou <span class=\"greek\">τι</span> alguém ou algo a alguém (Epict. 4, 12, 12 de Deus <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>; cf. Da 11:39 Theod.; TestJud 21:2; ApcSed 6:2; SibOr Fgm. 3, 12; Ar. [Milne 76, 49]; Menander Eph.: 783 Fgm. 1, 119 Jac. [em Jos., C. Ap. 1, 119]; Just., A I, 49, 7, A II 5, 2.—Cf. <span class=\"greek\">ὑπέταξεν</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐξουσίᾳ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">Πάρθους</span> Hippol., Ref. 9, 16, 4) 1 Cor 15:27c, 28c; Phil 3:21; Hb 2:5, 8b; Dg 10:2; Hm 12, 4, 2; AcPl Ha 8, 15. No mesmo sentido <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τινός</span> 1 Cor 15:27a; Eph 1:22; também <span class=\"greek\">ὑποκάτω</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">τινος</span> Hb 2:8a (Ps 8:7). <span class=\"greek\">ὑποτάσσειν</span> <span class=\"greek\">ἑαυτόν</span> <span class=\"greek\">τινι</span> sujeitar-se a alguém (Plut., Mor. 142e ao marido; Simplicius In Epict. p. 33 Düb. a poderes transcendentes) Hs 9, 22, 3.</p><p class=\"entry-text\">ⓑ Pass.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Tornar-se sujeito <span class=\"greek\">τινί</span> a uma pessoa ou a um estado de ser (Iren. 5, 5, 2 [Harv. II 332, 11]) Ro 8:20a; 1 Cor 15:28a; Hb 2:8c; 1 Pt 3:22; Dg 7:2; Pol 2:1. Abs. (Diod S 1, 55, 10; Aristobulus em Eus., PE 8, 10, 10 [=p. 140 Holladay] <span class=\"greek\">πάνθ</span>’ <span class=\"greek\">ὑποτέτακται</span>; Just., D. 85, 2 <span class=\"greek\">νικᾶται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑποτάσσεται</span> [Ath. 18, 2]; Iren. 1, 13, 4 [Harv. I 120, 7]) 1 Cor 15:27b.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Sujeitar-se, estar sujeito ou subordinado, obedecer, abs. (Jos., Bell. 4, 175) Ro 13:5; 1 Cor 14:34 (cf. <span class=\"greek\">δουλεύετε</span> <span class=\"greek\">ἀλλήλοις</span> Gal 5:13); 1 Cl 2:1a; 57:2. De submissão que envolve o reconhecimento de uma estrutura ordenada, com dat. da entidade a quem/à qual se demonstra o devido respeito (Palaeph. 38 p. 56, 15; 57, 2): para com um marido (v. Ps.-Callisth. 1, 22, 4 <span class=\"greek\">πρέπον</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γυναῖκα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">ὑποτάσσεσθαι</span>, v. 1a acima; cf. SEG 26, 1717, 26 [III/IV d.C.] num encantamento amoroso) Eph 5:22 v.l.; Col 3:18; Tit 2:5; 1 Pt 3:1 (sobre um alegado sentido imper. v. Schwyzer II 407), 5; pais Lk 2:51; senhores Tit 2:9; 1 Pt 2:18; B 19:7; D 4:11; autoridades seculares (1 Ch 29:24; Theoph. Ant. 1, 11 [p. 82, 14]) Ro 13:1 (CMorrison, The Powers That Be—Ro 13:1–13, diss. Basel ’56; EBarnikol, TU 77, ’61, 65–133 [não paulino]); Tit 3:1; 1 Pt 2:13; 1 Cl 61:1; dirigentes eclesiásticos 1 Cl 1:3; 57:1; IEph 2:2; IMg 2; 13:2; ITr 2:1f; 13:2; IPol 6:1; Pol 5:3; <span class=\"greek\">νεώτεροι</span> <span class=\"greek\">ὑποτάγητε</span> <span class=\"greek\">πρεσβυτέροις</span> 1 Pt 5:5. A Deus (Epict. 3, 24, 65 <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span> <span class=\"greek\">ὑποτεταγμένος</span>; 4, 12, 11; Ps 61:2; 2 Macc 9:12) 1 Cor 15:28b; Hb 12:9; Js 4:7; 1 Cl 20:1; IEph 5:3; a Cristo Eph 5:24. À vontade de Deus, à lei etc. Ro 8:7; 10:3; 1 Cl 34:5; Hm 12, 5, 1; <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιθυμίᾳ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀγαθῇ</span> 12, 2, 5.—De submissão no sentido de ceder voluntariamente em amor 1 Cor 16:16; Eph 5:21; 1 Pt 5:5b v.l.; 1 Cl 38:1.—Os espíritos malignos devem estar sujeitos aos discípulos que Jesus envia Lk 10:17, 20. Igualmente, os espíritos proféticos devem estar sujeitos aos profetas nos quais habitam 1 Cor 14:32.—HMerklein, Studien zu Jesus und Paulus (WUNT 105) ’98, 405–37.</p><p class=\"entry-text\">② Acrescentar um documento ao final de outro documento, anexar, apensar, aditar (comum em documentos oficiais, daí freq. em inscr., papiros; v. também Jos., Vi. 364, Ant. 16, 161; Just., A I, 68, 4; Mel., HE 4, 26, 14) as cartas de Ign. <span class=\"greek\">ὑποτεταγμέναι</span> <span class=\"greek\">εἰσὶν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιστολῇ</span> <span class=\"greek\">ταύτῃ</span> Pol 13:2.—M-M. EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποτεταγμένως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποτεταγμένως</span> adv. do part. perf. pass. de <span class=\"greek\">ὑποτάσσω</span> submissamente 1 Cl 37:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0372-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποτίθημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποτίθημι</span> fut. 2 sg. <span class=\"greek\">ὑποθήσεις</span> Ex 26:12; 27:5; 1 aor. <span class=\"greek\">ὑπέθηκα</span>; 2 aor. inf. <span class=\"greek\">ὑποθεῖναι</span>; 2 aor. méd. imper. <span class=\"greek\">ὑπόθου</span> (TestJob 23:7) (Hom. +).</p><p class=\"entry-text\">① At. depor algo como expressão de serviço, depor <span class=\"greek\">τὶ</span> algo.</p><p class=\"entry-text\">ⓐ Em expressão idiomática, depor, arriscar <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> (Lucian, Dem. 41 <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πατρίδος</span> <span class=\"greek\">τύχαις</span>; cf. Seneca, Ep. 47, 4; POxy 2722, 35 [comercial]) <span class=\"greek\">τὸν</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">τράχηλον</span> <span class=\"greek\">ὕπεθηκαν</span> puseram o próprio pescoço em risco (em meu benefício) ou, tendo em vista a predileção de Paulo por imagens comerciais: hipotecaram o próprio pescoço Ro 16:4.</p><p class=\"entry-text\">ⓑ Diferentemente (de certo modo como TestIss 5:3 <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">νῶτον</span>) curvar-se em submissão 1 Cl 63:1 (v. s.v. <span class=\"greek\">τράχηλος</span> para esta passagem e Ro 16:4).</p><p class=\"entry-text\">② Méd. (Hom. et al.) aor. <span class=\"greek\">ὑπεθέμην</span> (LXX) <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> proporcionar instrução, dar a conhecer, ensinar algo a alguém (Pla., Hipp. Maj. 286b) <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ὑποτιθέμενος</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀδελφοῖς</span> 1 Ti 4:6. Este sentido parece adequar-se melhor ao contexto do que sugerir ou indicar algo a alguém (Hom.; Hdt. 1, 90; Pla., Charm. 155d; papiros) ou prescrever, ordenar a alguém (fazer) algo (Hdt. 4, 134; Philo, Poster. Cai. 12; Jos., Bell. 2, 137, Ant. 1, 76).—M-M.</p></section></article>"};